1	/**
2	 * RAINBOW master course — ONE continuous route through the washer world.
3	 *
4	 * Units: 1 unit ≈ 5 cm at Benny's scale (Benny body radius ≈ 0.8). +Y is up (absolute altitude).
5	 * The route starts inside Drum A (scene 01/02), drains through a chute into the whirlpool basin (03),
6	 * drops down the five-arrow slide (04), winds through the perforated current tube (05), crests the
7	 * rinse arch (06), winds through the washer tube and then PLUNGES ~62 units straight down (07) before
8	 * the bottom of that same tube flares into the Final Spin Chamber inlet (08). 08–10 stay in that same
9	 * chamber; the route ends under the purple towel on the platform, where the 11 cinematic plays.
10	 *
11	 * Every stage is a range of arc-length `s` on a single centripetal Catmull-Rom spline, so position
12	 * and tangent are continuous by construction; `validateContinuity()` measures it anyway.
13	 */
14	import * as THREE from 'three';
15	
16	export type StageId = '01' | '02' | '03' | '04' | '05' | '06' | '07' | '08' | '09' | '10' | '11';
17	export type TubeKind = 'none' | 'chute' | 'gold' | 'perf';
18	export type StageProp = 'width' | 'tube' | 'speed' | 'bank';
19	
20	export interface StageDef {
21	  id: StageId;
22	  title: string;
23	  /** arc-length range on the course */
24	  s0: number;
25	  s1: number;
26	  /** water ribbon width (units) */
27	  width: number;
28	  /** enclosing tube radius (0 = open environment such as a drum/basin/chamber) */
29	  tube: number;
30	  tubeKind: TubeKind;
31	  /** auto-propulsion speed (units / s) */
32	  speed: number;
33	  /** coin counter shown in the locked reference screenshot of this stage */
34	  refCoins: number;
35	  interactive: boolean;
36	  /** banking strength multiplier */
37	  bank: number;
38	}
39	
40	export interface CourseSample {
41	  s: number;
42	  pos: THREE.Vector3;
43	  tan: THREE.Vector3;
44	  up: THREE.Vector3;
45	  right: THREE.Vector3;
46	}
47	
48	export const STAGE_TITLES: Record<StageId, string> = {
49	  '01': 'INSIDE THE WASHING MACHINE',
50	  '02': 'WHIRLPOOL TUMBLE',
51	  '03': 'WHIRLPOOL TWIRL',
52	  '04': 'THROUGH THE FIVE ARROWS',
53	  '05': 'FLOW INTO THE CURRENT',
54	  '06': 'CREST THE RINSE ARCH',
55	  '07': 'DIVE THE WASHER TUBE',
56	  '08': 'FINAL SPIN CHAMBER',
57	  '09': 'RIDE THE FINAL WAVE',
58	  '10': 'SLIDE INTO HIDING',
59	  '11': 'SAFELY HOME',
60	};
61	
62	/** Fixed world anchors shared by environment builders (absolute coordinates). */
63	export const WORLD = {
64	  drumA: { center: new THREE.Vector3(0, 0, 0), radius: 5, zBack: -6.5, zDoor: 3.5, doorRadius: 3.2, waterY: -2.5 },
65	  basin: { center: new THREE.Vector3(2, -16, -19), rimRadius: 11.5, rimY: -10.6, drainRadius: 4.3, drainY: -20.2 },
66	  /** Final Spin Chamber (08–11): drum with axis along Z, door at the far (-Z) end */
67	  chamber: { center: new THREE.Vector3(12, -101.1, 0), radius: 13.5, zBack: -280, zDoor: -332, floorY: -113.6, doorRadius: 6.2 },
68	  platform: { center: new THREE.Vector3(12, -110.6, -325.0), radius: 6.2, topY: -110.6 },
69	  plunge: { topY: -52, bottomY: -113.6 },
70	};
71	
72	/** funnel surface height of the whirlpool basin as a function of radius from its axis */
73	export function funnelY(r: number): number {
74	  const b = WORLD.basin;
75	  const t = THREE.MathUtils.clamp((r - b.drainRadius * 0.6) / (b.rimRadius - b.drainRadius * 0.6), 0, 1);
76	  return b.drainY + (b.rimY - b.drainY) * Math.pow(t, 0.72);
77	}
78	
79	const V = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
80	const smooth = (a: number, b: number, x: number) => {
81	  const t = THREE.MathUtils.clamp((x - a) / (b - a), 0, 1);
82	  return t * t * (3 - 2 * t);
83	};
84	
85	/**
86	 * A stretch whose tunnel axis is an exact straight line a→b (the stream winds inside it). The
87	 * course lies on the line at both ends of the stretch; tube.ts aligns the tunnel axis to it.
88	 */
89	export interface StraightAxis {
90	  /** arc-length range of the stretch on the course */
91	  s0: number;
92	  s1: number;
93	  a: THREE.Vector3;
94	  b: THREE.Vector3;
95	  /** stream-to-tunnel-bottom depth on the line (water sits this high in the tube) */
96	  floorDepth: number;
97	}
98	
99	interface RouteData {
100	  points: THREE.Vector3[];
101	  marks: Record<string, number>;
102	  straight: { from: string; to: string; a: THREE.Vector3; b: THREE.Vector3; floorDepth: number }[];
103	}
104	
105	/** Generates the dense control polyline of the route (absolute coordinates). */
106	function buildRoute(): RouteData {
107	  const pts: THREE.Vector3[] = [];
108	  const marks: Record<string, number> = {};
109	  const straight: RouteData['straight'] = [];
110	  const push = (p: THREE.Vector3) => {
111	    if (pts.length && p.distanceTo(pts[pts.length - 1]) < 0.25) return;
112	    pts.push(p);
113	  };
114	  const mark = (k: string) => (marks[k] = pts.length - 1);
115	  const seg = (n: number, f: (t: number) => THREE.Vector3, skipFirst = true) => {
116	    for (let i = skipFirst ? 1 : 0; i <= n; i++) push(f(i / n));
117	  };
118	
119	  // ---- 01: Benny hidden in the towel, drum A front-left floor (camera looks toward the door) ----
120	  const dA = WORLD.drumA;
121	  const hc = V(0, -0.4, 0); // swirl axis
122	  const th0 = Math.atan2(-2.0, 1.6);
123	  push(V(1.6, -2.4, -2.2));
124	  mark('01');
125	  // ---- 02: whirlpool tumble — helix around the drum axis toward the back drain ----
126	  const thEnd = -Math.PI / 2 - Math.PI * 2;
127	  seg(26, (t) => {
128	    const th = th0 + (thEnd - th0) * t;
129	    const r = 2.56 + (3.9 - 2.56) * smooth(0, 1, t);
130	    const z = -2.2 + (-5.4 + 2.2) * t;
131	    return V(hc.x + r * Math.cos(th), hc.y + r * Math.sin(th), z);
132	  });
133	  mark('02_drain');
134	  // chute from drum A back drain down into the whirlpool basin rim
135	  const b = WORLD.basin;
136	  const spiralStart = V(b.center.x - 9.6, funnelY(9.6) + 0.25, b.center.z);
137	  const c0 = pts[pts.length - 1].clone();
138	  const chuteCtrl = [c0, V(-0.6, -5.6, -7.6), V(-3.2, -7.8, -10.4), V(-6.6, -9.8, -14.2), spiralStart.clone().add(V(0, 0.15, 2.4))];
139	  const chute = new THREE.CatmullRomCurve3(chuteCtrl, false, 'centripetal');
140	  seg(14, (t) => chute.getPoint(t));
141	  push(spiralStart);
142	  mark('03');
143	  // ---- 03: whirlpool twirl — 3/4 inward turn down the funnel that dives into the drain CENTRE ----
144	  // decreasing angle from the -X side (θ=-π/2) round the far and right sides to the near (+Z) side;
145	  // r shrinks as (1-t)^1.6 so the last stretch heads radially inward = straight -Z into the drain hole.
146	  seg(60, (t) => {
147	    const th = -Math.PI / 2 - Math.PI * 1.5 * (1 - (1 - t) * (1 - t)); // angle eases out → radial finish
148	    const r = 9.6 * Math.pow(1 - t, 0.9);
149	    return V(b.center.x + r * Math.sin(th), funnelY(r) + 0.25, b.center.z + r * Math.cos(th));
150	  });
151	  mark('04');
152	  // ---- 04: five-arrow slide — steep straight drop (≈32°) inside the gold ring pipe ----
153	  const s4 = pts[pts.length - 1].clone();
154	  const pitch4 = THREE.MathUtils.degToRad(32);
155	  const d4 = V(0, -Math.sin(pitch4), -Math.cos(pitch4));
156	  // pull-down arc from the drain lip into the steep slide pitch
157	  const R4a = 9;
158	  seg(7, (t) => {
159	    const a = pitch4 * t;
160	    return s4.clone().add(V(0, -R4a * (1 - Math.cos(a)), -R4a * Math.sin(a)));
161	  });
162	  const s4b = pts[pts.length - 1].clone();
163	  seg(16, (t) => s4b.clone().addScaledVector(d4, 34 * t));
164	  // pull out of the slide into the horizontal current
165	  const s4c = pts[pts.length - 1].clone();
166	  const R4 = 12;
167	  seg(8, (t) => {
168	    const a = -pitch4 + pitch4 * t;
169	    return s4c.clone().add(V(0, R4 * (Math.cos(-pitch4) - Math.cos(a)), R4 * (Math.sin(-pitch4) - Math.sin(a))));
170	  });
171	  mark('05');
172	  // ---- 05: long STRAIGHT perforated current tube (ref 05: concentric rings, ONE vanishing point);
173	  // the wide stream winds in gentle S-curves inside it. Centreline = the straight line s5 → s5+L05
174	  // (slight descent); the lateral S-offset and its slope vanish at both ends, so 04 and 06 join it
175	  // tangentially and s6 (hence 06/07/plunge/08) is unchanged. tube.ts builds the 05 tunnel on L05.
176	  const s5 = pts[pts.length - 1].clone();
177	  const L05 = V(0, -3, -72);
178	  const S05 = { amp: 2.0, waves: 2 }; // ≈1.6 after smoothPolyline; λ ≈ 36 units
179	  seg(48, (t) => {
180	    const env = smooth(0, 0.16, t) * (1 - smooth(0.84, 1, t));
181	    return s5.clone().addScaledVector(L05, t).add(V(S05.amp * env * Math.sin(2 * Math.PI * S05.waves * t), 0, 0));
182	  });
183	  straight.push({ from: '05', to: '06', a: s5.clone(), b: s5.clone().add(L05), floorDepth: 3.3 });
184	  mark('06');
185	  // ---- 06: rinse arch — rises ~12 units, crests, curls down and to the right into the 07 tube ----
186	  const s6 = pts[pts.length - 1].clone();
187	  seg(34, (t) =>
188	    V(
189	      s6.x - 4 * Math.sin(Math.PI * t) + (WORLD.chamber.center.x - s6.x) * smooth(0.4, 1, t),
190	      s6.y + 12.5 * Math.pow(Math.sin(Math.PI * Math.min(t / 0.82, 1)), 1.15) - 4.5 * smooth(0.5, 1, t),
191	      s6.z - 46 * t,
192	    ),
193	  );
194	  mark('07');
195	  // ---- 07: winding washer tube (the visible stretch) ----
196	  const s7 = pts[pts.length - 1].clone();
197	  seg(32, (t) =>
198	    V(s7.x + 3.2 * Math.sin(3 * Math.PI * t) * Math.sin(Math.PI * t), s7.y + (WORLD.plunge.topY - s7.y) * t, s7.z - 60 * t),
199	  );
200	  mark('07_plunge_top');
201	  // ---- 07: THE DEEP PLUNGE — pull-down arc, long -70° straight, pull-up arc into the 08 inlet ----
202	  const p0 = pts[pts.length - 1].clone();
203	  const R = 14;
204	  const amax = THREE.MathUtils.degToRad(70);
205	  seg(12, (t) => {
206	    const a = amax * t;
207	    return p0.clone().add(V(0, -R * (1 - Math.cos(a)), -R * Math.sin(a)));
208	  });
209	  const p1 = pts[pts.length - 1].clone();
210	  const dPl = V(0, -Math.sin(amax), -Math.cos(amax));
211	  // straight length chosen so the bottom lands exactly on the chamber floor altitude
212	  const drop = p0.y - WORLD.plunge.bottomY;
213	  const Lstraight = (drop - 2 * R * (1 - Math.cos(amax))) / Math.sin(amax);
214	  seg(Math.ceil(Lstraight / 2), (t) => p1.clone().addScaledVector(dPl, Lstraight * t));
215	  mark('07_plunge_mid_end');
216	  const p2 = pts[pts.length - 1].clone();
217	  seg(12, (t) => {
218	    const a = -amax + amax * t;
219	    return p2.clone().add(V(0, R * (Math.cos(-amax) - Math.cos(a)), R * (Math.sin(-amax) - Math.sin(a))));
220	  });
221	  mark('07_plunge_bottom');
222	  const p3 = pts[pts.length - 1].clone();
223	  const zIn = WORLD.chamber.zBack;
224	  seg(4, (t) => V(p3.x, p3.y, p3.z + (zIn - p3.z) * t));
225	  mark('08');
226	  // ---- 08–10: Final Spin Chamber — winding stream toward the platform & towel ----
227	  const s8 = pts[pts.length - 1].clone();
228	  const plat = WORLD.platform;
229	  seg(14, (t) => V(s8.x + 3.6 * Math.sin(2 * Math.PI * t) * Math.sin(Math.PI * t), s8.y, s8.z - 15 * t));
230	  mark('09');
231	  const s9 = pts[pts.length - 1].clone();
232	  seg(14, (t) => V(s9.x - 3.2 * Math.sin(Math.PI * t), s9.y + 0.1 * t, s9.z - 15 * t));
233	  mark('10');
234	  const s10 = pts[pts.length - 1].clone();
235	  const end = V(plat.center.x, plat.topY + 0.45, plat.center.z + 0.6);
236	  seg(10, (t) =>
237	    V(s10.x + (end.x - s10.x) * t, s10.y + (end.y - s10.y) * smooth(0.3, 1, t), s10.z + (end.z - s10.z) * t),
238	  );
239	  mark('11');
240	  smoothPolyline(pts, marks['03'], 2.2, 3);
241	  return { points: pts, marks, straight };
242	}
243	
244	/**
245	 * Arc-length Gaussian smoothing of the polyline from index `from` to the end (endpoints fixed).
246	 * Removes tangent kinks where independently generated segments meet; the 02 tumble helix
247	 * (before `from`) is left untouched.
248	 */
249	function smoothPolyline(pts: THREE.Vector3[], from: number, sigma: number, passes: number) {
250	  for (let pass = 0; pass < passes; pass++) {
251	    const cum: number[] = [0];
252	    for (let i = 1; i < pts.length; i++) cum.push(cum[i - 1] + pts[i].distanceTo(pts[i - 1]));
253	    const out = pts.map((p) => p.clone());
254	    for (let i = from + 1; i < pts.length - 1; i++) {
255	      const acc = new THREE.Vector3();
256	      let wsum = 0;
257	      for (let j = i - 12; j <= i + 12; j++) {
258	        if (j < from || j >= pts.length) continue;
259	        const d = cum[j] - cum[i];
260	        const w = Math.exp(-(d * d) / (2 * sigma * sigma));
261	        acc.addScaledVector(pts[j], w);
262	        wsum += w;
263	      }
264	      out[i].copy(acc.divideScalar(wsum));
265	    }
266	    for (let i = from + 1; i < pts.length - 1; i++) pts[i].copy(out[i]);
267	  }
268	}
269	
270	export class Course {
271	  readonly curve: THREE.CatmullRomCurve3;
272	  readonly length: number;
273	  readonly stages: StageDef[];
274	  readonly marks: Record<string, number>; // arc-length of named marks
275	  /** straight tunnel stretches (05 current) — see StraightAxis */
276	  readonly straightAxes: StraightAxis[];
277	  private readonly N: number;
278	  private readonly ds: number;
279	  private readonly P: Float32Array;
280	  private readonly T: Float32Array;
281	  private readonly U: Float32Array;
282	
283	  constructor() {
284	    const route = buildRoute();
285	    this.curve = new THREE.CatmullRomCurve3(route.points, false, 'centripetal');
286	    // arc-length table over curve parameter u
287	    const M = route.points.length * 24;
288	    const us: number[] = [0];
289	    const ls: number[] = [0];
290	    let prev = this.curve.getPoint(0);
291	    for (let i = 1; i <= M; i++) {
292	      const u = i / M;
293	      const p = this.curve.getPoint(u);
294	      ls.push(ls[i - 1] + p.distanceTo(prev));
295	      us.push(u);
296	      prev = p;
297	    }
298	    this.length = ls[M];
299	    const uAtS = (s: number) => {
300	      let lo = 0, hi = M;
301	      while (hi - lo > 1) {
302	        const mid = (lo + hi) >> 1;
303	        if (ls[mid] < s) lo = mid; else hi = mid;
304	      }
305	      const f = (s - ls[lo]) / Math.max(1e-6, ls[hi] - ls[lo]);
306	      return us[lo] + (us[hi] - us[lo]) * f;
307	    };
308	    const sAtIndex = (i: number) => {
309	      const u = i / (route.points.length - 1);
310	      const k = Math.round(u * M);
311	      return ls[k];
312	    };
313	    this.marks = {};
314	    for (const [k, i] of Object.entries(route.marks)) this.marks[k] = sAtIndex(i);
315	    this.straightAxes = route.straight.map((r) => ({ s0: this.marks[r.from], s1: this.marks[r.to], a: r.a, b: r.b, floorDepth: r.floorDepth }));
316	
317	    // ---- stages ----
318	    const m = this.marks;
319	    const def = (id: StageId, s0: number, s1: number, o: Partial<StageDef>): StageDef => ({
320	      id, title: STAGE_TITLES[id], s0, s1, width: 5, tube: 0, tubeKind: 'none', speed: 11, refCoins: 0,
321	      interactive: true, bank: 1, ...o,
322	    });
323	    this.stages = [
324	      def('01', 0, 0.01, { width: 6, interactive: false, speed: 0 }),
325	      def('02', 0.01, m['03'], { width: 5, interactive: false, speed: 9, bank: 0 }),
326	      def('03', m['03'], m['04'], { width: 7, speed: 9, refCoins: 1330, bank: 2.2 }),
327	      def('04', m['04'], m['05'], { width: 4.4, tube: 4.8, tubeKind: 'gold', speed: 14, refCoins: 1330 }),
328	      // 05: level current (ref 05 shows no tilt) → weak curvature banking
329	      def('05', m['05'], m['06'], { width: 9, tube: 7.6, tubeKind: 'perf', speed: 11, refCoins: 1420, bank: 0.25 }),
330	      def('06', m['06'], m['07'], { width: 7, tube: 15, tubeKind: 'perf', speed: 11, refCoins: 1680, bank: 0.6 }),
331	      def('07', m['07'], m['08'], { width: 5.6, tube: 7.2, tubeKind: 'perf', speed: 12, refCoins: 1940 }),
332	      def('08', m['08'], m['09'], { width: 4.8, speed: 9.5, refCoins: 2040 }),
333	      def('09', m['09'], m['10'], { width: 6.4, speed: 9.5, refCoins: 2280 }),
334	      def('10', m['10'], m['11'], { width: 3.8, speed: 7.5, refCoins: 2500 }),
335	      def('11', m['11'], this.length, { width: 3, interactive: false, speed: 0, refCoins: 2500 }),
336	    ];
337	
338	    // ---- dense frame table (pos, tangent, banked up) ----
339	    this.N = Math.ceil(this.length / 0.25) + 1;
340	    this.ds = this.length / (this.N - 1); // exact spacing so the last interval is not short
341	    this.P = new Float32Array(this.N * 3);
342	    this.T = new Float32Array(this.N * 3);
343	    this.U = new Float32Array(this.N * 3);
344	    const pos: THREE.Vector3[] = [];
345	    const tan: THREE.Vector3[] = [];
346	    for (let i = 0; i < this.N; i++) {
347	      const s = Math.min(this.length, i * this.ds);
348	      const u = uAtS(s);
349	      pos.push(this.curve.getPoint(u));
350	      tan.push(this.curve.getTangent(u).normalize());
351	    }
352	    // up: world-up projected off the tangent + curvature banking, then smoothed
353	    const WU = new THREE.Vector3(0, 1, 0);
354	    const ups: THREE.Vector3[] = [];
355	    let prevUp = WU.clone();
356	    for (let i = 0; i < this.N; i++) {
357	      const t = tan[i];
358	      let up = WU.clone().addScaledVector(t, -WU.dot(t));
359	      if (up.lengthSq() < 1e-4) up = prevUp.clone().addScaledVector(t, -prevUp.dot(t));
360	      up.normalize();
361	      // banking from lateral curvature
362	      const i0 = Math.max(0, i - 4), i1 = Math.min(this.N - 1, i + 4);
363	      const k = tan[i1].clone().sub(tan[i0]).divideScalar((i1 - i0) * this.ds);
364	      const right = new THREE.Vector3().crossVectors(t, up).normalize();
365	      const st = this.stageAtS(i * this.ds);
366	      const bankAngle = THREE.MathUtils.clamp(-k.dot(right) * 6 * st.bank, -0.85, 0.85);
367	      up.applyAxisAngle(t, bankAngle);
368	      ups.push(up);
369	      prevUp = up;
370	    }
371	    // smooth up vectors (box filter) & re-orthogonalize
372	    const sm: THREE.Vector3[] = ups.map((_, i) => {
373	      const acc = new THREE.Vector3();
374	      for (let j = -8; j <= 8; j++) acc.add(ups[THREE.MathUtils.clamp(i + j, 0, this.N - 1)]);
375	      const t = tan[i];
376	      return acc.addScaledVector(t, -acc.dot(t)).normalize();
377	    });
378	    for (let i = 0; i < this.N; i++) {
379	      pos[i].toArray(this.P, i * 3);
380	      tan[i].toArray(this.T, i * 3);
381	      sm[i].toArray(this.U, i * 3);
382	    }
383	  }
384	
385	  stageAtS(s: number): StageDef {
386	    for (const st of this.stages) if (s < st.s1) return st;
387	    return this.stages[this.stages.length - 1];
388	  }
389	
390	  stage(id: StageId): StageDef {
391	    return this.stages.find((s) => s.id === id)!;
392	  }
393	
394	  /**
395	   * smoothly blended per-stage property (blend ±blend units around stage boundaries).
396	   * Accepts either argument order: prop(s, 'width') or prop('width', s).
397	   */
398	  prop(s: number, key: StageProp, blend?: number): number;
399	  prop(key: StageProp, s: number, blend?: number): number;
400	  prop(a: number | StageProp, b: number | StageProp, blend = 6): number {
401	    const s = (typeof a === 'number' ? a : b) as number;
402	    const key = (typeof a === 'string' ? a : b) as StageProp;
403	    let v = 0, w = 0;
404	    for (const st of this.stages) {
405	      const a = smooth(st.s0 - blend, st.s0 + blend, s) * (1 - smooth(st.s1 - blend, st.s1 + blend, s));
406	      if (a > 0) { v += st[key] * a; w += a; }
407	    }
408	    return w > 0 ? v / w : this.stageAtS(s)[key];
409	  }
410	
411	  widthAt(s: number): number {
412	    // the stream narrows into the towel opening at the very end of 10
413	    const st10 = this.stage('10');
414	    const base = this.prop(s, 'width');
415	    return base * (1 - 0.35 * smooth(st10.s1 - 8, st10.s1, s));
416	  }
417	
418	  sample(s: number, out?: CourseSample): CourseSample {
419	    const o = out ?? { s: 0, pos: new THREE.Vector3(), tan: new THREE.Vector3(), up: new THREE.Vector3(), right: new THREE.Vector3() };
420	    const x = THREE.MathUtils.clamp(s, 0, this.length) / this.ds;
421	    const i = Math.min(this.N - 2, Math.floor(x));
422	    const f = x - i;
423	    const lerp3 = (A: Float32Array, v: THREE.Vector3) =>
424	      v.set(
425	        A[i * 3] + (A[i * 3 + 3] - A[i * 3]) * f,
426	        A[i * 3 + 1] + (A[i * 3 + 4] - A[i * 3 + 1]) * f,
427	        A[i * 3 + 2] + (A[i * 3 + 5] - A[i * 3 + 2]) * f,
428	      );
429	    o.s = s;
430	    lerp3(this.P, o.pos);
431	    lerp3(this.T, o.tan).normalize();
432	    lerp3(this.U, o.up);
433	    o.up.addScaledVector(o.tan, -o.up.dot(o.tan)).normalize();
434	    o.right.crossVectors(o.tan, o.up).normalize();
435	    return o;
436	  }
437	
438	  /** world position on the water at arc-length s with lateral offset (− left, + right) and height */
439	  pointAt(s: number, lateral = 0, height = 0, out = new THREE.Vector3()): THREE.Vector3 {
440	    const f = this.sample(s);
441	    return out.copy(f.pos).addScaledVector(f.right, lateral).addScaledVector(f.up, height);
442	  }
443	}
444	
445	export interface ContinuityReport {
446	  ok: boolean;
447	  boundaries: { from: StageId; to: StageId; s: number; posGap: number; tangentAngleDeg: number; upAngleDeg: number; altitude: number }[];
448	  maxStepTangentDeg: number;
449	  maxStepPos: number;
450	  plunge: { entryAltitude07: number; plungeTop: { s: number; y: number }; plungeMid: { s: number; y: number }; plungeBottom: { s: number; y: number }; inlet08: { s: number; y: number }; verticalDrop: number; minPitchDeg: number };
451	}
452	
453	/** Numerical continuity validation of the whole route. */
454	export function validateContinuity(c: Course): ContinuityReport {
455	  const eps = 0.02;
456	  const boundaries = c.stages.slice(0, -1).map((st, i) => {
457	    const nx = c.stages[i + 1];
458	    const sa = Math.max(st.s1 - eps, 0);
459	    const sb = Math.min(st.s1 + eps, c.length); // 11 starts at the route end (cinematic)
460	    const a = c.sample(sa);
461	    const b = c.sample(sb);
462	    return {
463	      from: st.id,
464	      to: nx.id,
465	      s: +st.s1.toFixed(2),
466	      posGap: +(a.pos.distanceTo(b.pos) - (sb - sa)).toFixed(4),
467	      tangentAngleDeg: +THREE.MathUtils.radToDeg(a.tan.angleTo(b.tan)).toFixed(3),
468	      upAngleDeg: +THREE.MathUtils.radToDeg(a.up.angleTo(b.up)).toFixed(3),
469	      altitude: +a.pos.y.toFixed(2),
470	    };
471	  });
472	  let maxT = 0, maxP = 0;
473	  const step = 0.25;
474	  let prev = c.sample(0);
475	  let minPitch = 0;
476	  const rideStart = c.stage('03').s0; // 01–02 tumble helix is a cinematic, checked for gaps only
477	  for (let s = step; s <= c.length; s += step) {
478	    const cur = c.sample(s);
479	    if (s > rideStart + step) maxT = Math.max(maxT, THREE.MathUtils.radToDeg(prev.tan.angleTo(cur.tan)));
480	    maxP = Math.max(maxP, prev.pos.distanceTo(cur.pos));
481	    if (s > c.marks['07_plunge_top'] && s < c.marks['08']) minPitch = Math.min(minPitch, THREE.MathUtils.radToDeg(Math.asin(cur.tan.y)));
482	    prev = { ...cur, pos: cur.pos.clone(), tan: cur.tan.clone(), up: cur.up.clone(), right: cur.right.clone() };
483	  }
484	  const y = (s: number) => +c.sample(s).pos.y.toFixed(2);
485	  const top = c.marks['07_plunge_top'];
486	  const bottom = c.marks['07_plunge_bottom'];
487	  const mid = (top + bottom) / 2;
488	  const inlet = c.marks['08'];
489	  const plunge = {
490	    entryAltitude07: y(c.stage('07').s0),
491	    plungeTop: { s: +top.toFixed(2), y: y(top) },
492	    plungeMid: { s: +mid.toFixed(2), y: y(mid) },
493	    plungeBottom: { s: +bottom.toFixed(2), y: y(bottom) },
494	    inlet08: { s: +inlet.toFixed(2), y: y(inlet) },
495	    verticalDrop: +(y(top) - y(inlet)).toFixed(2),
496	    minPitchDeg: +minPitch.toFixed(1),
497	  };
498	  const ok =
499	    boundaries.every((b) => Math.abs(b.posGap) < 0.01 && b.tangentAngleDeg < 1 && b.upAngleDeg < 2) &&
500	    maxP < step * 1.05 &&
501	    maxT < 8 && // ≥1.8-unit turn radius anywhere on the ride (tightest: the drop into the 03 drain)
502	    plunge.verticalDrop > 50 &&
503	    plunge.inlet08.y < plunge.entryAltitude07 - 50;
504	  return { ok, boundaries, maxStepTangentDeg: +maxT.toFixed(3), maxStepPos: +maxP.toFixed(4), plunge };
505	}
