1	/**
2	 * Third-person ride camera: behind/above Benny, looking along his heading (the course tangent), or
3	 * along the straight tunnel axis inside the 05–07 tube so the gold rings converge to one vanishing point
4	 * as in the references. Pitch & roll follow the banked path smoothly — including the 07 plunge.
5	 */
6	import * as THREE from 'three';
7	import { WORLD } from '../world/course';
8	import type { Course, StageId } from '../world/course';
9	import type { TubePath } from '../world/tube';
10	
11	export interface CamParams {
12	  back: number; // distance behind Benny
13	  up: number; // height above Benny's water point
14	  ahead: number; // look-at distance ahead
15	  lookUp: number; // look-at height
16	  fov: number;
17	  latFollow: number; // 1 = camera fully follows Benny's lateral offset
18	  roll: number; // 0..1 how much of the path bank the camera adopts
19	}
20	
21	export const STAGE_CAM: Partial<Record<StageId, CamParams>> = {
22	  '03': { back: 6.5, up: 6.5, ahead: 6, lookUp: -1.5, fov: 64, latFollow: 0.3, roll: 0.3 },
23	  '04': { back: 8.5, up: 5.2, ahead: 14, lookUp: -3.0, fov: 66, latFollow: 0.6, roll: 0.4 },
24	  // 05: level rear chase down the straight current tube; pitch atan((up-lookUp)/(ahead+back)) ≈ 12°
25	  // below the tunnel axis puts the ring vanishing point ~1/3 down the frame (ref 05), Benny low-centre
26	  '05': { back: 6.1, up: 3.7, ahead: 18, lookUp: -1.5, fov: 62, latFollow: 0.92, roll: 0 },
27	  '06': { back: 5.6, up: 2.6, ahead: 12, lookUp: 3.4, fov: 66, latFollow: 0.7, roll: 0.4 },
28	  '07': { back: 6.4, up: 4.1, ahead: 18, lookUp: 1.8, fov: 62, latFollow: 0.6, roll: 0.6 },
29	  '08': { back: 6.2, up: 3.7, ahead: 16, lookUp: 0.2, fov: 62, latFollow: 0.8, roll: 0.3 },
30	  '09': { back: 6.2, up: 3.7, ahead: 15, lookUp: 0.6, fov: 62, latFollow: 0.8, roll: 0.3 },
31	  '10': { back: 5.8, up: 3.4, ahead: 11, lookUp: 1.2, fov: 62, latFollow: 0.8, roll: 0.2 },
32	};
33	
34	const KEYS: (keyof CamParams)[] = ['back', 'up', 'ahead', 'lookUp', 'fov', 'latFollow', 'roll'];
35	
36	export function camParamsAt(course: Course, s: number, blend = 8): CamParams {
37	  const acc: CamParams = { back: 0, up: 0, ahead: 0, lookUp: 0, fov: 0, latFollow: 0, roll: 0 };
38	  let w = 0;
39	  for (const st of course.stages) {
40	    const p = STAGE_CAM[st.id];
41	    if (!p) continue;
42	    const a = THREE.MathUtils.smoothstep(s, st.s0 - blend, st.s0 + blend) * (1 - THREE.MathUtils.smoothstep(s, st.s1 - blend, st.s1 + blend));
43	    if (a <= 0) continue;
44	    for (const k of KEYS) acc[k] += p[k] * a;
45	    w += a;
46	  }
47	  if (w === 0) return { ...(STAGE_CAM['03'] as CamParams) };
48	  for (const k of KEYS) acc[k] /= w;
49	  return acc;
50	}
51	
52	export class RideCamera {
53	  readonly pos = new THREE.Vector3();
54	  readonly target = new THREE.Vector3();
55	  readonly up = new THREE.Vector3(0, 1, 0);
56	  fov = 70;
57	  private init = false;
58	  /** optional straight tunnel axis + the s-range where the camera aligns to it */
59	  axis: { path: TubePath; s0: number; s1: number } | null = null;
60	
61	  constructor(private course: Course) {}
62	
63	  /** desired pose for Benny at (s, lateral) */
64	  desired(s: number, lat: number, outPos: THREE.Vector3, outTarget: THREE.Vector3, outUp: THREE.Vector3): CamParams {
65	    const p = camParamsAt(this.course, s);
66	    const f = this.course.sample(s);
67	    const fb = this.course.sample(Math.max(0, s - p.back * 0.5)); // smoothing of heading
68	    const dir = f.tan.clone().lerp(fb.tan, 0.35).normalize();
69	    let up = f.up.clone();
70	    if (this.axis) {
71	      const a = this.axis;
72	      const w = THREE.MathUtils.smoothstep(s, a.s0, a.s0 + 10) * (1 - THREE.MathUtils.smoothstep(s, a.s1 - 10, a.s1));
73	      if (w > 0) {
74	        const af = a.path.frame(s);
75	        dir.lerp(af.tan, w).normalize();
76	        up.lerp(af.up, w).normalize();
77	      }
78	    }
79	    up.addScaledVector(dir, -up.dot(dir)).normalize();
80	    const right = new THREE.Vector3().crossVectors(dir, up).normalize();
81	    const benny = f.pos.clone().addScaledVector(f.right, lat);
82	    const anchor = benny.clone().addScaledVector(right, -lat * (1 - p.latFollow));
83	    // offsets use an 'upright' up: banking only tilts the camera as much as `roll` allows
84	    const upPos = new THREE.Vector3(0, 1, 0).lerp(up, Math.max(p.roll, Math.abs(dir.y))).normalize();
85	    // position: ON the curved course behind Benny (stays inside bending/pitching tubes, e.g. the
86	    // 07 pull-up arc); aim: along his heading so he stays centred in winding streams
87	    const fbk = this.course.sample(Math.max(0, s - p.back));
88	    const upB = new THREE.Vector3(0, 1, 0).lerp(fbk.up, Math.max(p.roll, Math.abs(fbk.tan.y))).normalize();
89	    const straightPos = anchor.clone().addScaledVector(dir, -p.back).addScaledVector(upPos, p.up);
90	    const curvedPos = fbk.pos.clone().addScaledVector(fbk.right, lat * p.latFollow).addScaledVector(upB, p.up);
91	    // use the curved position where the path bends in pitch (plunge arcs), straight elsewhere
92	    const pitchBend = THREE.MathUtils.clamp(Math.abs(fbk.tan.y - f.tan.y) * 6, 0, 1);
93	    outPos.copy(straightPos).lerp(curvedPos, Math.max(pitchBend, 0.35));
94	    outTarget.copy(anchor).addScaledVector(dir, p.ahead).addScaledVector(upPos, p.lookUp);
95	    outUp.set(0, 1, 0).lerp(up, p.roll).normalize();
96	    // 03 whirlpool: dynamic high angle from the near side, looking down into the vortex toward the
97	    // drain and the porthole wall (Benny left, drain lower-right as in the reference)
98	    const st3 = this.course.stage('03');
99	    const w3 = THREE.MathUtils.smoothstep(s, st3.s0 - 6, st3.s0 + 2) * (1 - THREE.MathUtils.smoothstep(s, st3.s1 - 6, st3.s1 + 1));
100	    if (w3 > 0) {
101	      const B = WORLD.basin;
102	      const wp = benny.clone().add(new THREE.Vector3(2.8, 3.6, 5.6));
103	      const drain = new THREE.Vector3(B.center.x, B.drainY, B.center.z);
104	      const wt = benny.clone().lerp(drain, 0.2).add(new THREE.Vector3(0.6, -1.0, -2.4));
105	      outPos.lerp(wp, w3);
106	      outTarget.lerp(wt, w3);
107	      outUp.lerp(new THREE.Vector3(0, 1, 0), w3).normalize();
108	    }
109	    // 05 straight current tube: the '05' preset measured in the straight tunnel's own frame — aimed
110	    // along the tunnel axis (not Benny's S-curve heading) so the gold rings stay concentric on ONE
111	    // vanishing point, level (no roll), following Benny's lateral S offset by latFollow.
112	    const st5 = this.course.stage('05');
113	    const p5 = STAGE_CAM['05'] as CamParams;
114	    const w5 = this.axis ? THREE.MathUtils.smoothstep(s, st5.s0 + 1, st5.s0 + 8) * (1 - THREE.MathUtils.smoothstep(s, st5.s1 - 9, st5.s1 - 1)) : 0;
115	    if (w5 > 0 && this.axis) {
116	      const af = this.axis.path.frame(s);
117	      const T = af.tan.clone();
118	      const U = new THREE.Vector3(0, 1, 0).addScaledVector(T, -T.y).normalize();
119	      const Rt = new THREE.Vector3().crossVectors(T, U).normalize();
120	      const water = f.pos.clone().addScaledVector(f.right, lat); // Benny's point on the stream
121	      const off = water.clone().sub(af.pos).dot(Rt); // his lateral offset from the tunnel axis
122	      const cp = water.addScaledVector(T, -p5.back).addScaledVector(U, p5.up).addScaledVector(Rt, -off * (1 - p5.latFollow));
123	      const pitch = Math.atan2(p5.up - p5.lookUp, p5.ahead + p5.back);
124	      const look = T.multiplyScalar(Math.cos(pitch)).addScaledVector(U, -Math.sin(pitch));
125	      outPos.lerp(cp, w5);
126	      outTarget.lerp(cp.clone().addScaledVector(look, p5.ahead + p5.back), w5);
127	      outUp.lerp(U, w5).normalize();
128	    }
129	    return p;
130	  }
131	
132	  update(dt: number, s: number, lat: number, cam: THREE.PerspectiveCamera, snap = false) {
133	    const dp = new THREE.Vector3(), dt3 = new THREE.Vector3(), du = new THREE.Vector3();
134	    const p = this.desired(s, lat, dp, dt3, du);
135	    const k = snap || !this.init ? 1 : 1 - Math.exp(-dt * 7);
136	    const kt = snap || !this.init ? 1 : 1 - Math.exp(-dt * 9);
137	    this.pos.lerp(dp, k);
138	    this.target.lerp(dt3, kt);
139	    this.up.lerp(du, kt).normalize();
140	    this.fov += (p.fov - this.fov) * (snap || !this.init ? 1 : Math.min(1, dt * 3));
141	    this.init = true;
142	    cam.position.copy(this.pos);
143	    cam.up.copy(this.up);
144	    cam.lookAt(this.target);
145	    if (Math.abs(cam.fov - this.fov) > 0.01) { cam.fov = this.fov; cam.updateProjectionMatrix(); }
146	  }
147	}
