1	/**
2	 * RAINBOW game: one connected 3D world, one continuous route.
3	 *   intro  (01–02)  real-time cinematic: the girl drops the towel bundle (Benny hidden) into Drum A,
4	 *                   closes the door and walks away; Benny peeks, then the spin tumbles him down the drain.
5	 *   ride   (03–10)  interactive: auto-propelled along the course, steer left/right, real coin pickups,
6	 *                   5 hearts (bumping the foam walls costs one), pause/resume.
7	 *   outro  (11)     real-time victory cinematic: Benny is hidden under the towel; the SAME girl opens the
8	 *                   door, folds/holds the towel without ever seeing him; FINAL SPIN COMPLETE.
9	 * window.__rainbow exposes a deterministic QA API used by scripts/capture.mjs.
10	 */
11	import * as THREE from 'three';
12	import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
13	import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
14	import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass.js';
15	import { OutputPass } from 'three/examples/jsm/postprocessing/OutputPass.js';
16	import { Course, StageId, WORLD } from '../world/course';
17	import { buildEnvironment } from '../world/environment';
18	import { createCandyEnvironment, createRenderer } from '../render/env';
19	import { createGradePass } from '../render/grade';
20	import { createHud } from '../ui/hud';
21	import { findCinematic, playCinematic } from '../ui/cinematicVideo';
22	import { createCoins, COIN_VALUE } from '../gameplay/coins';
23	import { createInput } from '../gameplay/input';
24	import { RideCamera } from './cameraRig';
25	import { loadBennyRuntime, loadGirlRuntime, loadWater, moduleStatus } from './modules';
26	
27	type Mode = 'intro' | 'ride' | 'outro' | 'end';
28	const START_COINS = 1330;
29	const STAGE_ORDER: StageId[] = ['01', '02', '03', '04', '05', '06', '07', '08', '09', '10', '11'];
30	const sm = (a: number, b: number, x: number) => THREE.MathUtils.smoothstep(x, a, b);
31	const lerp = THREE.MathUtils.lerp;
32	
33	/** intro timeline marks (seconds) */
34	const T = { dropEnd: 1.6, doorClose0: 1.9, doorClose1: 2.8, walk0: 3.0, peek: 4.4, cp01: 6.6, spin: 7.4, cp02: 9.1, drain: 11.4, rideStart: 14.0 };
35	/** outro timeline marks */
36	const O = { hide: 0.6, walk0: 0.0, door0: 1.1, door1: 2.1, lean0: 1.9, fold0: 2.7, fold1: 3.7, hold: 6.4, badge: 3.9, cp11: 5.2 };
37	
38	export async function startGame(canvas: HTMLCanvasElement) {
39	  const qs = new URLSearchParams(location.search);
40	  const qaMode = qs.has('qa');
41	  const renderer = createRenderer(canvas, { preserveDrawingBuffer: qaMode });
42	  const dpr = qs.has('dpr') ? Number(qs.get('dpr')) : Math.min(window.devicePixelRatio || 1, 2);
43	  renderer.setPixelRatio(dpr);
44	  const scene = new THREE.Scene();
45	  scene.environment = createCandyEnvironment(renderer);
46	  scene.background = new THREE.Color('#b23fb4');
47	  const fog = new THREE.FogExp2('#ffbde9', 0.0035);
48	  scene.fog = fog;
49	  scene.add(new THREE.HemisphereLight('#fff0ff', '#a33bb8', 1.15));
50	  const sun = new THREE.DirectionalLight('#fff4e6', 1.6);
51	  sun.position.set(0.3, 1, 0.45);
52	  scene.add(sun);
53	  scene.add(sun.target);
54	  const fill = new THREE.PointLight('#ffd8ff', 30, 30, 1.6);
55	  scene.add(fill);
56	
57	  const camera = new THREE.PerspectiveCamera(66, 9 / 16, 0.05, 1200);
58	  const composer = new EffectComposer(renderer);
59	  composer.addPass(new RenderPass(scene, camera));
60	  const bloom = new UnrealBloomPass(new THREE.Vector2(256, 256), 0.2, 0.35, 0.94);
61	  const useBloom = qs.get('bloom') !== '0';
62	  if (useBloom) composer.addPass(bloom);
63	  composer.addPass(new OutputPass());
64	  composer.addPass(createGradePass());
65	
66	  const resize = () => {
67	    const w = canvas.clientWidth || window.innerWidth;
68	    const h = canvas.clientHeight || window.innerHeight;
69	    renderer.setSize(w, h, false);
70	    composer.setSize(w, h);
71	    bloom.resolution.set(w / 2, h / 2);
72	    camera.aspect = w / h;
73	    camera.updateProjectionMatrix();
74	  };
75	  window.addEventListener('resize', resize);
76	  resize();
77	
78	  // ---------------------------------------------------------------- world
79	  const course = new Course();
80	  const env = buildEnvironment(course);
81	  scene.add(env.group);
82	  const water = await loadWater(course);
83	  scene.add(water.group);
84	  const benny = await loadBennyRuntime();
85	  scene.add(benny.root);
86	  const girl = await loadGirlRuntime();
87	  const coins = createCoins(course);
88	  scene.add(coins.group);
89	  // debug: ?hide=water,benny,coins,drumA,basin,tubes,chamber
90	  const hidden = new Set((qs.get('hide') ?? '').split(',').filter(Boolean));
91	  if (hidden.has('water')) water.group.visible = false;
92	  if (hidden.has('coins')) coins.group.visible = false;
93	  const zoneHidden = (k: string) => hidden.has(k);
94	  const hud = createHud();
95	  const input = createInput(canvas);
96	  const rideCam = new RideCamera(course);
97	  rideCam.axis = env.tubeAxis;
98	
99	  // ---------------------------------------------------------------- state
100	  const st = {
101	    mode: 'intro' as Mode,
102	    t: 0, // time within the current mode
103	    clock: 0, // global animation time (shaders)
104	    frozen: null as number | null, // QA: freeze shader time
105	    s: 0,
106	    lat: 0,
107	    vlat: 0,
108	    coins: START_COINS,
109	    hearts: 5,
110	    paused: false,
111	    stage: '01' as StageId,
112	    bumpCooldown: 0,
113	    edgeTime: 0,
114	    twirl: 0,
115	    respawns: 0,
116	    log: [] as { t: number; s: number; y: number; stage: StageId }[],
117	  };
118	
119	  const stageOf = (s: number): StageId => course.stageAtS(s).id;
120	
121	  const setStage = (id: StageId) => {
122	    if (st.stage === id) return;
123	    st.stage = id;
124	    hud.setStage(id);
125	    updateZones();
126	  };
127	
128	  const zoneRanges: Record<keyof typeof env.zones, [StageId, StageId]> = {
129	    drumA: ['01', '02'],
130	    basin: ['02', '05'],
131	    tubes: ['03', '09'],
132	    chamber: ['07', '11'],
133	  };
134	  const updateZones = () => {
135	    const i = STAGE_ORDER.indexOf(st.stage);
136	    for (const [k, [a, b]] of Object.entries(zoneRanges)) {
137	      env.zones[k as keyof typeof env.zones].visible = !zoneHidden(k) && i >= STAGE_ORDER.indexOf(a) && i <= STAGE_ORDER.indexOf(b);
138	    }
139	    const inDrum = i <= 1;
140	    fog.density = inDrum ? 0.0015 : i >= 7 ? 0.0025 : 0.0035;
141	  };
142	
143	  // girl placement helpers (she lives in laundry-room local frames)
144	  const placeGirl = (room: 'A' | 'C', local: THREE.Vector3, yaw: number) => {
145	    const anchor = room === 'A' ? env.roomA.anchor : env.roomC.anchor;
146	    if (girl.root.parent !== anchor) anchor.add(girl.root);
147	    girl.root.position.copy(local);
148	    girl.root.rotation.set(0, yaw, 0);
149	  };
150	
151	  const bennyPose = (s: number, lat: number, time: number, out: { pos: THREE.Vector3; quat: THREE.Quaternion }) => {
152	    const f = course.sample(s);
153	    const h = water.surfaceHeight(s, lat, time);
154	    out.pos.copy(f.pos).addScaledVector(f.right, lat).addScaledVector(f.up, h + benny.radius * 0.55);
155	    const m = new THREE.Matrix4().makeBasis(new THREE.Vector3().crossVectors(f.up, f.tan).normalize(), f.up, f.tan);
156	    out.quat.setFromRotationMatrix(m);
157	    return f;
158	  };
159	
160	  const pose = { pos: new THREE.Vector3(), quat: new THREE.Quaternion() };
161	  const tmpV = new THREE.Vector3();
162	  const doorAOpen = -1.9, doorCOpen = -1.95;
163	
164	  // ---------------------------------------------------------------- intro (01–02)
165	  const introUpdate = (dt: number) => {
166	    const t = st.t;
167	    const wc = (water as unknown as { controls?: { drumSwirl: number; drumAgitation: number; outro: number } }).controls;
168	    if (wc) {
169	      wc.drumAgitation = 0.35 + 0.65 * sm(T.spin - 0.5, T.spin + 0.8, t);
170	      wc.drumSwirl = sm(T.spin, T.spin + 1.2, t) * (1 - sm(T.drain + 0.5, T.rideStart, t));
171	      wc.outro = 0;
172	    }
173	    const dA = WORLD.drumA;
174	    const start = course.sample(0).pos;
175	    // --- girl: drop the load, close the door, walk away at normal pace (never looks back)
176	    const spots = env.roomA.spots;
177	    if (t < T.walk0) {
178	      placeGirl('A', new THREE.Vector3(1.2, spots.nearDoor.y, 7.6), Math.PI);
179	      girl.play(t < T.dropEnd ? 'dropLoad' : 'closeDoor', { fade: 0.25 });
180	    } else {
181	      const k = THREE.MathUtils.clamp((t - T.walk0 - 0.35) / 4.6, 0, 1);
182	      const from = new THREE.Vector3(1.2, spots.nearDoor.y, 7.6);
183	      const p = from.clone().lerp(spots.exitLeft, k);
184	      const dir = spots.exitLeft.clone().sub(from);
185	      const yawWalk = Math.atan2(dir.x, dir.z);
186	      const turn = sm(T.walk0, T.walk0 + 0.6, t);
187	      placeGirl('A', p, lerp(Math.PI, yawWalk, turn));
188	      girl.play('walk', { fade: 0.3 });
189	    }
190	    // --- door A
191	    env.doorA.rotation.y = lerp(doorAOpen, 0, sm(T.doorClose0, T.doorClose1, t));
192	    // --- towel bundle flies from her hands into the drum, Benny hidden inside
193	    const handW = girl.handR.getWorldPosition(tmpV).clone();
194	    const k = sm(0.35, T.dropEnd, t);
195	    const towelRest = start.clone().add(new THREE.Vector3(0.15, -1.25, 0.05));
196	    const arc = handW.clone().lerp(towelRest, k);
197	    arc.y += Math.sin(k * Math.PI) * 1.2;
198	    let sB = 0;
199	    if (t >= T.spin && st.stage === '01') { st.stage = '02'; hud.setStage('02'); }
200	    if (t < T.spin) {
201	      env.drumTowel.mesh.position.copy(t < 0.35 ? handW : arc);
202	      env.drumTowel.mesh.rotation.set(0, 0.4, 0);
203	      env.drumTowel.setBundle(1);
204	      env.drumTowel.mesh.scale.setScalar(0.62);
205	      // Benny inside the bundle; peeks out only once she has turned away
206	      const peek = sm(T.peek, T.peek + 0.7, t);
207	      benny.root.visible = peek > 0.02;
208	      benny.setExpression('peek');
209	      bennyPose(0, 0, st.clock, pose);
210	      benny.root.position.copy(start).add(new THREE.Vector3(0, -1.0 + 1.35 * peek, 0));
211	      benny.root.quaternion.setFromEuler(new THREE.Euler(0, Math.PI + 0.25, 0)); // facing the camera (inside drum)
212	      benny.update(dt, { swim: 0, steer: 0, speed: 0, time: st.clock });
213	    } else {
214	      // spin: tumble along the 02 helix, then the chute
215	      const u = sm(T.spin, T.rideStart, t);
216	      const s03 = course.stage('03').s0;
217	      sB = s03 * (t < T.drain ? 0.55 * sm(T.spin, T.drain, t) : 0.55 + 0.45 * sm(T.drain, T.rideStart, t));
218	      void u;
219	      benny.root.visible = true;
220	      benny.setExpression(t < T.drain + 1.2 ? 'dizzy' : 'happy');
221	      const f = bennyPose(sB, 0, st.clock, pose);
222	      // inside Drum A the swirl carries him along the helix itself (no ribbon surface there yet)
223	      const inDrum = 1 - sm(T.drain - 0.4, T.drain + 0.6, t);
224	      // the swirl lifts him toward the middle of the drum while he tumbles (ref 02), then he drops to the drain
225	      const hp = course.sample(sB).pos;
226	      const toAxis = sm(T.spin, T.spin + 1.0, t) * (1 - sm(T.drain - 1.6, T.drain - 0.2, t)) * 0.45;
227	      hp.x *= 1 - toAxis; hp.y = hp.y + (0.2 - hp.y) * toAxis;
228	      benny.root.position.copy(pose.pos).lerp(hp, inDrum);
229	      const tumble = sm(T.rideStart - 1.0, T.rideStart, t);
230	      // tumble = rolling cartwheels seen by the camera: face the lens, roll around the view axis
231	      const toCam = cam02(benny.root.position).pos.clone().sub(benny.root.position).normalize();
232	      const face = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 0, 1), toCam);
233	      const roll = new THREE.Quaternion().setFromAxisAngle(toCam, Math.sin(t * 1.7) * 0.9 + t * 1.1);
234	      const wobble = new THREE.Quaternion().setFromEuler(new THREE.Euler(Math.sin(t * 2.3) * 0.35, Math.sin(t * 1.9) * 0.4, 0));
235	      const spinQ = roll.multiply(face).multiply(wobble);
236	      benny.root.quaternion.copy(spinQ).slerp(pose.quat, tumble);
237	      benny.update(dt, { swim: 0.4, steer: 0, speed: 8, time: st.clock, tumble: tumble < 0.99 });
238	      // towel lags behind and unravels in the drum
239	      const sT = Math.max(0, sB - 2.6);
240	      const ft = course.sample(Math.min(sT, course.marks['02_drain'] - 1));
241	      env.drumTowel.mesh.position.copy(ft.pos).addScaledVector(ft.up, -0.4);
242	      env.drumTowel.mesh.rotation.set(t * 0.8, t * 0.5, 0.3);
243	      env.drumTowel.setBundle(lerp(1, 0.45, sm(T.spin, T.cp02, t)));
244	      env.drumTowel.mesh.scale.setScalar(lerp(0.62, 0.8, sm(T.spin, T.cp02, t)));
245	      void f;
246	    }
247	    st.s = sB;
248	    // --- floating laundry
249	    const sw = t < T.spin ? 0 : (t - T.spin) * 1.6;
250	    env.laundry.sock.position.set(Math.cos(2.3 + sw) * 2.2 - 0.6, -1.5 + Math.sin(st.clock * 1.3) * 0.15 + Math.sin(2.3 + sw) * (t < T.spin ? 0 : 1.6), 0.6 - sw * 0.25);
251	    env.laundry.sock.rotation.set(0.3 + sw, 0.6, 0.9 + st.clock * 0.3);
252	    env.laundry.shirt.position.set(-2.0 + Math.cos(0.4 + sw) * (t < T.spin ? 0 : 2.0), -1.6 + Math.sin(st.clock * 1.1 + 1) * 0.15 + (t < T.spin ? 0 : Math.sin(0.4 + sw) * 2.2), 0.9 - sw * 0.2);
253	    env.laundry.shirt.rotation.set(-1.15 + sw * 0.7, 0.2 + sw, 0.15);
254	    env.laundry.shirt.scale.setScalar(0.62);
255	    env.laundry.sock.scale.setScalar(0.62);
256	    // --- cameras
257	    if (t < T.spin + 0.6) {
258	      // 01: inside the drum looking out through the door, Benny peeking in the foreground
259	      camera.position.set(0.85, -1.05, -6.05);
260	      camera.up.set(0, 1, 0);
261	      camera.lookAt(-0.05, -0.2, dA.zDoor);
262	      setFov(64);
263	    } else if (t < T.drain) {
264	      // 02: tumbling with the swirl; the door ring above (deterministic blend from the 01 shot)
265	      const c2 = cam02(benny.root.position);
266	      const k2 = sm(T.spin + 0.6, T.spin + 1.6, t);
267	      const p01 = new THREE.Vector3(0.85, -1.05, -6.05), l01 = new THREE.Vector3(-0.05, -0.2, dA.zDoor);
268	      camera.position.copy(p01.lerp(c2.pos, k2));
269	      camera.up.set(0, 1, 0);
270	      camera.lookAt(l01.lerp(c2.look, k2));
271	      setFov(lerp(64, 68, k2));
272	    } else {
273	      // chute chase cam, blending into the ride camera framing for 03
274	      const kk = sm(T.drain, T.rideStart, t);
275	      const back = course.pointAt(Math.max(0, sB - 3.6), 0, 1.7);
276	      const look = course.pointAt(sB + 4, 0, 0.2);
277	      const rp = new THREE.Vector3(), rt = new THREE.Vector3(), ru = new THREE.Vector3();
278	      rideCam.desired(Math.max(course.stage('03').s0, sB), 0, rp, rt, ru);
279	      camera.position.lerp(back.lerp(rp, kk * kk), 0.15);
280	      camera.up.set(0, 1, 0);
281	      camera.lookAt(look.lerp(rt, kk * kk));
282	      setFov(lerp(66, 64, kk));
283	    }
284	    if (t >= T.rideStart) startRide();
285	  };
286	
287	  /** 02 camera: between Benny and the drum's back wall, looking past him to the door ring */
288	  const cam02 = (b: THREE.Vector3) => {
289	    const dA = WORLD.drumA;
290	    const door = new THREE.Vector3(0, 0.3, dA.zDoor);
291	    const away = b.clone().sub(door).normalize();
292	    const pos = b.clone().addScaledVector(away, 3.0).add(new THREE.Vector3(0, 0.35, 0));
293	    const rr = Math.hypot(pos.x, pos.y);
294	    if (rr > 2.7) { pos.x *= 2.7 / rr; pos.y *= 2.7 / rr; }
295	    pos.y = Math.max(pos.y, dA.waterY + 1.0);
296	    pos.z = THREE.MathUtils.clamp(pos.z, dA.zBack + 0.4, dA.zDoor - 1);
297	    const look = b.clone().lerp(door, 0.22).add(new THREE.Vector3(0, 0.45, 0));
298	    return { pos, look };
299	  };
300	
301	  const setFov = (f: number) => {
302	    if (Math.abs(camera.fov - f) > 0.01) { camera.fov = f; camera.updateProjectionMatrix(); }
303	  };
304	
305	  const startRide = () => {
306	    st.mode = 'ride';
307	    st.t = 0;
308	    st.s = course.stage('03').s0;
309	    st.lat = 0;
310	    hud.setVisible(true);
311	    setStage('03');
312	    rideCam.pos.copy(camera.position);
313	    rideCam.target.copy(camera.position).add(camera.getWorldDirection(new THREE.Vector3()).multiplyScalar(10));
314	    rideCam.fov = camera.fov;
315	    hud.showHint('Drag or hold left / right to steer');
316	    setTimeout(() => hud.showHint(null), 3500);
317	  };
318	
319	  // ---------------------------------------------------------------- ride (03–10)
320	  const rideUpdate = (dt: number) => {
321	    input.update(dt);
322	    const stg = course.stageAtS(st.s);
323	    const speed = course.prop('speed', st.s);
324	    st.s = Math.min(course.stage('11').s0, st.s + speed * dt);
325	    const halfW = course.widthAt(st.s) / 2;
326	    const safe = halfW - 0.75;
327	    st.vlat += (input.steer * 7.5 - st.vlat) * Math.min(1, dt * 8);
328	    st.lat = THREE.MathUtils.clamp(st.lat + st.vlat * dt, -halfW + 0.55, halfW - 0.55);
329	    // foam-wall bump → lose a heart (with cooldown), bounce back toward the centre
330	    st.bumpCooldown = Math.max(0, st.bumpCooldown - dt);
331	    if (Math.abs(st.lat) > safe) st.edgeTime += dt; else st.edgeTime = 0;
332	    if (st.edgeTime > 0.6 && st.bumpCooldown <= 0) {
333	      st.hearts = Math.max(0, st.hearts - 1);
334	      hud.setHearts(st.hearts);
335	      hud.flashHurt();
336	      st.bumpCooldown = 1.6;
337	      st.vlat = -Math.sign(st.lat) * 9;
338	      water.splash(benny.root.position, course.sample(st.s).up, 1);
339	      if (st.hearts === 0) {
340	        // restart this stage with full hearts (checkpoint), coins kept
341	        st.hearts = 5;
342	        hud.setHearts(5);
343	        st.s = stg.s0;
344	        st.lat = 0;
345	        st.respawns++;
346	      }
347	    }
348	    // coins
349	    const got = coins.update(st.clock, dt, st.s, st.lat);
350	    if (got) { st.coins += got * COIN_VALUE; hud.setCoins(st.coins); }
351	    setStage(stageOf(st.s));
352	    // Benny
353	    const f = bennyPose(st.s, st.lat, st.clock, pose);
354	    benny.root.position.copy(pose.pos);
355	    const lean = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 0, 1), -input.steer * 0.25);
356	    // 03 whirlpool twirl: Benny spins around his up axis while riding the vortex
357	    st.twirl = st.stage === '03' ? st.twirl + dt * 2.2 : st.twirl * Math.max(0, 1 - dt * 3);
358	    const tw = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), st.stage === '03' ? Math.PI + Math.sin(st.twirl) * 0.9 : 0);
359	    benny.root.quaternion.copy(pose.quat).multiply(tw).multiply(lean);
360	    benny.root.visible = true;
361	    benny.setExpression('happy');
362	    benny.update(dt, { swim: 1, steer: input.steer, speed, time: st.clock });
363	    water.wake(pose.pos, f.tan, f.right, speed, dt);
364	    // camera
365	    rideCam.update(dt, st.s, st.lat, camera);
366	    // towel: folded in 08/09, lifted into a tent as the stream reaches it (late 09 → 10)
367	    env.towel.setTent(sm(course.stage('09').s1 - 6, course.stage('10').s0 + 2, st.s));
368	    // girl at the counter behind the door glass in 10 (back turned — never sees Benny)
369	    if (st.stage === '09' || st.stage === '10') {
370	      placeGirl('C', env.roomC.spots.table.clone(), 0.25);
371	      girl.play('laundryCounter', { fade: 0.3 });
372	    }
373	    env.doorC.rotation.y = 0;
374	    st.log.push({ t: st.clock, s: st.s, y: benny.root.position.y, stage: st.stage });
375	    if (st.log.length > 20000) st.log.shift();
376	    if (st.s >= course.stage('11').s0 - 0.01) startOutro();
377	  };
378	
379	  // ---------------------------------------------------------------- outro (11)
380	  const cinematic = { ending: null as string | null };
381	  const startOutro = () => {
382	    st.mode = 'outro';
383	    st.t = 0;
384	    setStage('11');
385	    if (cinematic.ending) {
386	      // optional Flow ending video; the real-time 11 frame (girl holds towel, FINAL SPIN COMPLETE) follows
387	      st.paused = true;
388	      void playCinematic(cinematic.ending, { onEnding: () => { st.t = Math.max(st.t, O.badge - 0.4); st.paused = false; } });
389	    }
