/**
 * Offline geometry probe for checkpoint 05: reproduces the ride camera exactly (snap) and projects
 * the tunnel VP, ring centres/extents, the stream centreline, Benny's anchor and the coins.
 * run: cd /home/user/rainbow- && npx vite-node <this file> [s offset] [lat]
 */
import * as THREE from '/home/user/rainbow-/node_modules/three/build/three.module.js';
import { Course } from '/home/user/rainbow-/src/world/course.ts';
import { straightTubePath, tubeCenterAt } from '/home/user/rainbow-/src/world/tube.ts';
import { RideCamera } from '/home/user/rainbow-/src/game/cameraRig.ts';
import { coinLayout } from '/home/user/rainbow-/src/gameplay/coins.ts';

const W = 864, H = 1536;
const course = new Course();
const s05 = course.stage('05').s0, s08 = course.stage('08').s0;
const perfPath = straightTubePath(course, s05, s08, { window: 30, taper: 14, baseRadius: (s) => course.prop('tube', s) });
const rc = new RideCamera(course);
rc.axis = { path: perfPath, s0: s05, s1: course.marks['07_plunge_top'] };
const argOff = process.argv[2] ? Number(process.argv[2]) : NaN;
const cpOff = Number.isFinite(argOff) ? argOff : Number(process.env.CP ?? 12.7);
const s = s05 + cpOff;
const lat = Number(process.argv[3] ?? 0);
const p = new THREE.Vector3(), t = new THREE.Vector3(), u = new THREE.Vector3();
const prm = rc.desired(s, lat, p as any, t as any, u as any);
const cam = new THREE.PerspectiveCamera(prm.fov, W / H, 0.05, 1200);
cam.position.copy(p); cam.up.copy(u); cam.lookAt(t); cam.updateMatrixWorld(true); cam.updateProjectionMatrix();
const scr = (v: THREE.Vector3) => { const q = v.clone().project(cam); return [Math.round((q.x + 1) / 2 * W), Math.round((1 - q.y) / 2 * H), q.z]; };
const depth = (v: THREE.Vector3) => v.clone().applyMatrix4(cam.matrixWorldInverse).z * -1;
const out: any = { s05: +s05.toFixed(2), s06: +course.stage('06').s0.toFixed(2), s, fov: prm.fov, cam: p.toArray().map((x) => +x.toFixed(2)) };
const af = perfPath.frame(s);
out.axisTan = af.tan.toArray().map((x: number) => +x.toFixed(4));
const vp = scr(p.clone().addScaledVector(af.tan, 5000));
out.VP = vp.slice(0, 2);
const f = course.sample(s);
const water = f.pos.clone().addScaledVector(f.right, lat);
out.camAboveWater = +(p.y - water.y).toFixed(2);
out.camBehind = +water.clone().sub(p).dot(af.tan).toFixed(2);
out.camLatFromAxis = +p.clone().sub(af.pos).dot(af.right).toFixed(2);
out.bennyLatFromAxis = +water.clone().sub(af.pos).dot(af.right).toFixed(2);
out.radius = +perfPath.radius(s).toFixed(2);
out.depth = +perfPath.depth(s).toFixed(2);
out.width = +course.widthAt(s).toFixed(2);
const anchor = water.clone().addScaledVector(f.up, 0.44 + 0.3);
out.bennyAnchor = scr(anchor).slice(0, 2);
out.bennyWater = scr(water).slice(0, 2);
out.bennyDepth = +depth(water).toFixed(2);
// rings
const rings: any[] = [];
for (let rs = s05 + 3; rs <= s08 - 1 && rings.length < 14; rs += 7.2) {
  if (rs < s - 7) continue;
  const fr = perfPath.frame(rs);
  const c = tubeCenterAt(perfPath, rs);
  const r = perfPath.radius(rs);
  let xs: number[] = [], ys: number[] = [];
  for (let k = 0; k < 64; k++) {
    const a = (k / 64) * Math.PI * 2;
    const q = c.clone().addScaledVector(fr.right, Math.cos(a) * r).addScaledVector(fr.up, Math.sin(a) * r);
    if (depth(q) < 0.1) continue;
    const [x, y] = scr(q); xs.push(x); ys.push(y);
  }
  const top = scr(c.clone().addScaledVector(fr.up, r));
  const cc = scr(c);
  rings.push({ s: +(rs - s05).toFixed(1), d: +depth(c).toFixed(1), centre: cc.slice(0, 2), top: top.slice(0, 2), xMid: Math.round((Math.min(...xs) + Math.max(...xs)) / 2), w: Math.max(...xs) - Math.min(...xs), tanDeg: +THREE.MathUtils.radToDeg(fr.tan.angleTo(af.tan)).toFixed(2) });
}
out.rings = rings;
// stream centreline (cyan core if the water core follows the course) ahead of Benny
const core: any[] = [];
for (let ds = -4; ds <= 64; ds += 2) {
  const fs = course.sample(s + ds);
  const q = fs.pos.clone();
  const hw = course.widthAt(s + ds) / 2;
  const [x, y, z] = scr(q);
  const l = scr(fs.pos.clone().addScaledVector(fs.right, -hw)), r = scr(fs.pos.clone().addScaledVector(fs.right, hw));
  core.push({ ds, xy: [x, y], edgeL: l[0], edgeR: r[0], latAx: +fs.pos.clone().sub(perfPath.frame(s + ds).pos).dot(perfPath.frame(s + ds).right).toFixed(2) });
}
out.core = core;
// coins
